raw_shacl_shapes:
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix ux: <http://sophia.ai/ux#> .
@prefix domain: <http://sophia.ai/domain#> .

ux:DomainDashboardFreshnessShape a sh:NodeShape ;
    sh:targetClass ux:DashboardSurface ;
    sh:property [ sh:path domain:freshnessPolicy ; sh:in ( "unknown-on-missing-or-error" ) ; sh:severity sh:Violation ] ;
    sh:property [ sh:path domain:freshnessMaxAgeSeconds ; sh:minExclusive 0 ; sh:severity sh:Violation ] .
